#' RD Compare Methods
#'
#' 
#' @param data .
#' @param outcome .
#' @param running .
#' @param treatment .
#' @param covs .
#' @param cluster .
#' @param cutoff .
#' @param level .
#' @param cmpBw .
#' @param cmpKernel .
#' @param cmpOrder .
#' @param cmpHonest .
#' @param cmpLocrand .
#' @param wLocrand .
#' @param reps .
#' @param seed .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$cmp} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cmpPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cmp$asDF}
#'
#' \code{as.data.frame(results$cmp)}
#'
#' @export
rdcmp <- function(
    data,
    outcome,
    running,
    treatment,
    covs,
    cluster,
    cutoff = 0,
    level = 95,
    cmpBw = TRUE,
    cmpKernel = TRUE,
    cmpOrder = TRUE,
    cmpHonest = TRUE,
    cmpLocrand = TRUE,
    wLocrand = 0,
    reps = 1000,
    seed = 1,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("rdcmp requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(running)) running <- jmvcore::resolveQuo(jmvcore::enquo(running))
    if ( ! missing(treatment)) treatment <- jmvcore::resolveQuo(jmvcore::enquo(treatment))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(running), running, NULL),
            `if`( ! missing(treatment), treatment, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(cluster), cluster, NULL))


    options <- rdcmpOptions$new(
        outcome = outcome,
        running = running,
        treatment = treatment,
        covs = covs,
        cluster = cluster,
        cutoff = cutoff,
        level = level,
        cmpBw = cmpBw,
        cmpKernel = cmpKernel,
        cmpOrder = cmpOrder,
        cmpHonest = cmpHonest,
        cmpLocrand = cmpLocrand,
        wLocrand = wLocrand,
        reps = reps,
        seed = seed,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- rdcmpClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

